{
  "schema_version": 1,
  "policies": [
    {
      "id": "unlimited-approval-deny",
      "policy": "// dambi default v2 policy — explorer id: GEN-01 (unlimited ERC20 approval
// to a non-allowlisted spender).
//
// An `approve(spender, amount)` with `amount == U256::MAX` hands `spender` an
// open-ended claim on the token — the canonical token-drain primitive.
//
// STATIC detection: `amount` is a raw lowercase U256 hex String (`{:#x}`, no
// leading zeros) on the BASE context, so the two canonical "unlimited" sentinels
// are matched by string equality — `uint256::MAX` (64 f's, standard ERC20
// max-approve) and `uint160::MAX` (40 f's, the Permit2-style max). No enrichment
// is needed, so this works fully offline (server-independent).
//
// NOTE: this slice was rewritten from the earlier `context.custom.approvalIsUnlimited`
// form, which depended on the `approval.unlimited_over_balance` policy_rpc method.
// That method is NOT implemented, and its output is `required: true`, so the manifest
// tripped `SystemFail` on EVERY approve (deny-all) once the bundle's manifest was
// actually shipped. The static check denies ONLY a genuinely unlimited approve and
// lets bounded approvals pass. (Over-balance scoring — approve-amount vs holdings —
// is dropped here; it needs balance enrichment and returns in a later increment.)
//
// The allowlist (spenders for whom an unlimited approval is expected) is inlined
// as a Cedar set literal; the entry below is the canonical Permit2 contract.
// Addresses are lowercase hex.
@id("unlimited-approval-deny")
@severity("warn")
forbid(principal, action == Token::Action::"Erc20Approve", resource)
when {
  (context.amount == "0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"
   || context.amount == "0xffffffffffffffffffffffffffffffffffffffff")
  && !(["0x000000000022d473030f116ddee9f6b43ac78ba3"].contains(context.spender))
};
",
      "manifest": {
        "id": "unlimited-approval-deny",
        "schema_version": 2,
        "trigger": {
          "where": {
            "action.tag": {
              "eq": "erc20_approve"
            }
          }
        }
      }
    },
    {
      "id": "send-first-time-or-burn-recipient-warn",
      "policy": "// dambi default v2 policy — demand signal: irreversible-typo-fatfinger-send
// (Send Safety Set). Coinbase/MetaMask/ENS/Bitdeer all warn that a confirmed
// transfer is irreversible; the most certain way to lose funds permanently is a
// send to the burn / zero address.
//
// `recipient` is a base, non-optional `String` field of
// `Token::Erc20TransferContext` (same shape as swap-recipient-not-self-deny),
// so this judges with NO enrichment and NO policy_rpc — it just compares the
// recipient against the known burn-address literals. Addresses are lowercase
// hex on both sides (host-normalized), so exact String equality / Set membership
// holds. The zero address and 0x…dead have no key holder: a transfer there is
// permanent loss, hence `deny` (a hard block, not a one-beat warn).
//
// NOTE (dedup): the originating signal also bundled a "first-time recipient,
// pause" warn. That half duplicates the existing draft
// transfer-unknown-recipient-warn (same threat, severity, and external history
// Bool) and is intentionally NOT carried here; this policy keeps only the novel
// burn-address clause.
@id("send-first-time-or-burn-recipient-warn")
@severity("deny")
@reason("This send goes to a burn address (0x000…000 / 0x…dead) — funds sent there are permanently lost")
forbid(principal, action == Token::Action::"Erc20Transfer", resource)
when {
  ["0x0000000000000000000000000000000000000000",
   "0x000000000000000000000000000000000000dead"].contains(context.recipient)
};
",
      "manifest": {
        "id": "send-first-time-or-burn-recipient-warn",
        "schema_version": 2,
        "trigger": {
          "where": {
            "action.tag": {
              "eq": "erc20_transfer"
            }
          }
        }
      }
    },
    {
      "id": "unknown-blind-sign-warning",
      "policy": "// dambi default v2 policy — explorer id: GEN-09 (blind / opaque signature).
//
// Warn whenever an action could not be decoded by any manifest and therefore
// surfaces as `Core::Action::"Unknown"` (opaque EIP-712, raw `eth_sign`, or
// calldata no adapter matched). Signature-phishing leans on exactly these
// undecodable requests, so the wallet should flag them for a human look.
//
// This is a pure action-shape policy (Aggregator type 8 — Decode
// Introspection): the verdict depends only on the decoded action's *identity*,
// not on any enriched fact. The manifest therefore declares no `policy_rpc`
// calls and no `custom_context`.
@id("unknown-blind-sign-warning")
@severity("warn")
forbid(principal, action == Core::Action::"Unknown", resource);
",
      "manifest": {
        "id": "unknown-blind-sign-warning",
        "schema_version": 2,
        "trigger": {
          "where": {
            "action.domain": {
              "eq": "unknown"
            }
          }
        }
      }
    },
    {
      "id": "permit2-sign-allowance-confirm",
      "policy": "// Default v2 policy — confirm before signing a Permit2 token allowance.
//
// EIP-712 `Permit2` allowance signatures (`permit2_sign_allowance`) grant a
// `spender` an off-chain-authorized allowance on the underlying token — a major
// phishing surface. Like the HyperLiquid agent-approval confirm, we warn on
// every such signature so the user reviews the decoded spender / amount /
// deadline before approving. Unconditional (no `when`): `spender`/`amount` are
// statically decoded, so this manifest declares no policy_rpc calls.
@id("permit2-sign-allowance-confirm")
@severity("warn")
@reason("Signing a Permit2 token allowance — confirm the spender and amount before approving")
forbid(
  principal,
  action == Token::Action::"Permit2SignAllowance",
  resource
);
",
      "manifest": {
        "id": "permit2-sign-allowance-confirm",
        "schema_version": 2,
        "trigger": {
          "where": {
            "action.tag": {
              "eq": "permit2_sign_allowance"
            }
          }
        },
        "policy_rpc": [],
        "custom_context": {
          "fields": {}
        }
      }
    },
    {
      "id": "swap-recipient-not-self-deny",
      "policy": "// dambi default v2 policy — explorer id: UNI-01 (swap output redirected to
// an address other than the signer).
//
// Drainers dress a swap up as normal but flip only `recipient` to the attacker:
// you sell your tokens and someone else receives the proceeds. `recipient` is a
// base `String` field of `Amm::SwapContext` and `principal.address` is the
// evaluated wallet's address (Wallet entity attr) — both non-optional Strings —
// so this compares directly with NO enrichment and NO policy_rpc (sv = COV).
// Addresses are lowercase hex on both sides, so exact String equality holds.
@id("swap-recipient-not-self-deny")
@severity("deny")
@reason("This swap sends the bought tokens to an address that is not your wallet")
forbid(principal, action == Amm::Action::"Swap", resource)
when { context.recipient != principal.address };
",
      "manifest": {
        "id": "swap-recipient-not-self-deny",
        "schema_version": 2,
        "trigger": {
          "where": {
            "action.tag": {
              "eq": "swap"
            }
          }
        }
      }
    }
  ],
  "sequence": "42",
  "issued_at": 1799999940,
  "expires_at": 1800003600,
  "env": "fixture",
  "profile": "day1-safety",
  "registry_ref": null
}
